# Verify the solution
sol = solution

# Check all givens
for idx, val in givens.items():
    if sol[idx] != val:
        print(f"MISMATCH at {idx}: expected {val}, got {sol[idx]}")

# Check rows
for r in range(N):
    row = set(sol[r*N:(r+1)*N])
    if len(row) != N or row != set(range(1, N+1)):
        print(f"Bad row {r}")

# Check cols
for c in range(N):
    col = set(sol[r*N + c] for r in range(N))
    if len(col) != N or col != set(range(1, N+1)):
        print(f"Bad col {c}")

# Check blocks
for br in range(B):
    for bc in range(B):
        block = []
        for r in range(br*B, (br+1)*B):
            for c in range(bc*B, (bc+1)*B):
                block.append(sol[r*N + c])
        if set(block) != set(range(1, N+1)):
            print(f"Bad block {br},{bc}")

print("All checks passed!")
print(sol)
